const bw = 20e6;
const tRise = 0.35 / bw;
const lLead = 100e-9;
const diDt = 10 / 1e-6;
const vLead = lLead * diDt;

const relTen = 0.1 / 10;
const relHalf = 0.1 / 0.5;
const rss = Math.sqrt(0.01 ** 2 + 0.02 ** 2);
const rssVolt = 6 * rss;
const vPeak = 10;
const vRms = vPeak / Math.SQRT2;
const vAvg = (vPeak * 2) / Math.PI;
const iBurden = 10 / 10.1;
const vNom = 6;
const vHi = 10 * 3030 / (1980 + 3030);
const vLo = 10 * 2970 / (2020 + 2970);

const tJ = 150;
const tA = 25;
const rTh = 40;
const pAllow = (tJ - tA) / rTh;
const idAt40 = pAllow / 40;
const vAt10 = pAllow / 10;
const zRatio = 0.2;
const pPulse = pAllow / zRatio;

